{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table rainandrainbow-wh.maplemonk.RAR_inventory_fact_items as WITH daily_sku_sales AS ( SELECT CAST(order_date AS DATE) AS date_day, upper(SKU_Code) as sku, SUM(quantity) AS daily_quantity from rainandrainbow-wh.MAPLEMONK.rainandrainbow_wh_sales_consolidated s WHERE SKU_Code is not null GROUP BY 1,2 ), daily_inventory_snapshot AS ( SELECT DATE(DATETIME_ADD( PARSE_TIMESTAMP(\'%Y-%m-%dT%H:%M:%E*S%Ez\', i.timeStamp), INTERVAL 3 HOUR)) date_day, replace(i.skuCode,\'`\',\'\') sku, sum(cast(Inventory as INT64)) as inventory_that_day, CASE WHEN ifnull(sum(cast(Inventory as INT64)),0) > 0 THEN 1 ELSE 0 END AS has_inventory, CASE WHEN ifnull(sum(cast(Inventory as INT64)),0) < 4 THEN 1 ELSE 0 END AS is_oos FROM rainandrainbow-wh.maplemonk.Unicommerce_rainandrainbow_unicommerce_get_inventory_snapshot i GROUP BY 1,2 ORDER BY 1 DESC ), all_sku_dates AS ( SELECT DISTINCT c.date_day, d.sku, FROM daily_inventory_snapshot AS d CROSS JOIN ( SELECT date_day FROM UNNEST(GENERATE_DATE_ARRAY(DATE \'2026-01-01\', CURRENT_DATE())) AS date_day ) AS c ), sales_metrics AS ( SELECT a.date_day, a.sku, COALESCE(s.daily_quantity, 0) AS daily_quantity, COALESCE(i.has_inventory, 0) AS has_inventory_today, inventory_that_day, ifnull(i.is_oos, 1) AS is_oos_today, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku ORDER BY a.date_day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS L7_day_sales, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku ORDER BY a.date_day ROWS BETWEEN 13 PRECEDING AND CURRENT ROW) AS L14_day_sales, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku ORDER BY a.date_day ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS L30_day_sales, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku ORDER BY a.date_day ROWS BETWEEN 44 PRECEDING AND CURRENT ROW) AS L45_day_sales, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku ORDER BY a.date_day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS inventory_days_7, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku ORDER BY a.date_day ROWS BETWEEN 13 PRECEDING AND CURRENT ROW) AS inventory_days_14, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku ORDER BY a.date_day ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS inventory_days_30, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku ORDER BY a.date_day ROWS BETWEEN 44 PRECEDING AND CURRENT ROW) AS inventory_days_45, SUM(IFNULL(i.is_oos, 0)) OVER (PARTITION BY a.sku ORDER BY a.date_day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS oos_days_7, SUM(IFNULL(i.is_oos, 0)) OVER (PARTITION BY a.sku ORDER BY a.date_day ROWS BETWEEN 13 PRECEDING AND CURRENT ROW) AS oos_days_14, SUM(IFNULL(i.is_oos, 0)) OVER (PARTITION BY a.sku ORDER BY a.date_day ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS oos_days_30, SUM(IFNULL(i.is_oos, 0)) OVER (PARTITION BY a.sku ORDER BY a.date_day ROWS BETWEEN 44 PRECEDING AND CURRENT ROW) AS oos_days_45 FROM all_sku_dates AS a LEFT JOIN daily_sku_sales AS s ON a.date_day = s.date_day AND a.sku = s.sku LEFT JOIN daily_inventory_snapshot AS i ON a.date_day = i.date_day AND a.sku = i.sku order by 1 desc ) SELECT date_day as data_fetch_date, s.sku, p.product_name, p.category, p.size, p.URL, s.daily_quantity, s.has_inventory_today, s.inventory_that_day as available_inventory, L7_day_sales sold_quantity_7_days, L14_day_sales sold_quantity_14_days, L30_day_sales sold_quantity_30_days, L45_day_sales sold_quantity_45_days, inventory_days_7, inventory_days_14, inventory_days_30, inventory_days_45, oos_days_7, oos_days_14, oos_days_30, oos_days_45 FROM sales_metrics s LEFT JOIN (select * from (select product_name, category, size, mrp, cost as cogs, URL, SKU_Code, row_number()over (partition by SKU_Code order by length(ifnull(SKU_Code,\'\')) desc) rw from rainandrainbow-wh.maplemonk.RAR_SKU_MASTER ) where rw = 1 ) p on upper(p.SKU_Code) = upper(s.sku) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            